import React from 'react';
import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import FindSchemes from './pages/FindSchemes';
import SchemeDetails from './pages/SchemeDetails';
import Auth from './pages/Auth';
import HowItWorks from './pages/HowItWorks';
import FAQs from './pages/FAQs';
import Settings from './pages/Settings';
import ChatWidget from './components/ChatWidget';

// Helper to scroll to top on route change
const ScrollToTop = () => {
  const { pathname } = useLocation();
  React.useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const App: React.FC = () => {
  return (
    <Router>
      <ScrollToTop />
      <div className="flex flex-col min-h-screen">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/find-schemes" element={<FindSchemes />} />
            <Route path="/scheme/:id" element={<SchemeDetails />} />
            <Route path="/auth" element={<Auth />} />
            <Route path="/how-it-works" element={<HowItWorks />} />
            <Route path="/faqs" element={<FAQs />} />
            <Route path="/settings" element={<Settings />} />
          </Routes>
        </main>
        <Footer />
        <ChatWidget />
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Search, User, Menu, X, ChevronRight, LogOut, Settings, ChevronDown } from 'lucide-react';

const Navbar: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [user, setUser] = useState<any>(null);
  const profileRef = useRef<HTMLDivElement>(null);

  const isActive = (path: string) => location.pathname === path;

  useEffect(() => {
    // Mock auth session using localStorage
    const checkUser = () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (savedUser) {
        setUser(JSON.parse(savedUser));
      } else {
        setUser(null);
      }
    };

    checkUser();
    window.addEventListener('storage', checkUser);
    return () => window.removeEventListener('storage', checkUser);
  }, [location.pathname]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('gov_smart_user');
    setUser(null);
    setIsProfileOpen(false);
    navigate('/');
    window.dispatchEvent(new Event('storage'));
  };

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Find Schemes', path: '/find-schemes' },
    { name: 'How It Works', path: '/how-it-works' },
    { name: 'FAQs', path: '/faqs' },
  ];

  const userDisplayName = user?.username || 'User';

  return (
    <nav className="bg-white border-b border-gray-100 sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20 items-center">

          <div className="flex-shrink-0 flex items-center">
            <Link to="/" className="flex items-center gap-3">
              <div className="bg-navy p-2 rounded-xl shadow-lg shadow-navy/10">
                <span className="text-white font-black text-xl tracking-tighter">GS</span>
              </div>
              <div className="hidden sm:block">
                <span className="text-navy font-bold text-xl block leading-tight">Gov-Smart</span>
                <span className="text-[10px] text-orange-500 font-bold uppercase tracking-wider block">AI-Powered Portal</span>
              </div>
            </Link>
          </div>

          <div className="hidden lg:flex flex-1 justify-center">
            <div className="flex items-center gap-x-10">
              {navLinks.map((link) => (
                <Link 
                  key={link.path}
                  to={link.path} 
                  className={`relative py-2 text-sm font-bold transition-all duration-300 ${
                    isActive(link.path) 
                    ? 'text-navy' 
                    : 'text-gray-400 hover:text-navy'
                  }`}
                >
                  {link.name}
                  {isActive(link.path) && (
                    <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-primary rounded-full animate-in fade-in zoom-in duration-300"></span>
                  )}
                </Link>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-x-6">
            <div className="hidden md:flex items-center gap-x-6 pr-6 border-r border-gray-100">
              <button className="text-gray-400 hover:text-navy transition-colors">
                <Search size={20} />
              </button>
            </div>

            {user ? (
              <div className="relative" ref={profileRef}>
                <button 
                  onClick={() => setIsProfileOpen(!isProfileOpen)}
                  className="flex items-center gap-2 p-1 bg-gray-50 rounded-full border border-gray-200 hover:border-orange-200 transition-all hover:bg-white group overflow-hidden"
                >
                  <div className="relative w-9 h-9 bg-navy rounded-full flex items-center justify-center text-white">
                    <User size={18} />
                    <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-green-500 rounded-full border-2 border-white shadow-sm"></div>
                  </div>
                  <ChevronDown size={14} className={`text-gray-400 mx-1.5 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`} />
                </button>

                {isProfileOpen && (
                  <div className="absolute right-0 mt-3 w-64 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="p-5 bg-gray-50/50 border-b border-gray-100">
                      <p className="text-sm font-bold text-navy truncate">{userDisplayName}</p>
                      <p className="text-xs text-gray-400 truncate">{user.email}</p>
                    </div>
                    <div className="p-2">
                      <Link to="/settings" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-semibold text-gray-600 hover:bg-gray-50 hover:text-navy rounded-xl transition-all">
                        <Settings size={18} /> Profile Settings
                      </Link>
                      <hr className="my-2 border-gray-100" />
                      <button 
                        onClick={handleLogout}
                        className="w-full flex items-center gap-3 px-4 py-3 text-sm font-semibold text-red-500 hover:bg-red-50 rounded-xl transition-all"
                      >
                        <LogOut size={18} /> Sign Out
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <Link 
                to="/auth" 
                className="hidden sm:flex items-center gap-2 px-6 py-2.5 bg-navy text-white hover:bg-orange-primary font-bold text-sm rounded-xl transition-all duration-300 shadow-md shadow-navy/10"
              >
                <User size={18} />
                <span>Sign In</span>
              </Link>
            )}

            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="lg:hidden p-2 rounded-xl hover:bg-gray-100 text-navy transition-all"
            >
              {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

      <div 
        className={`lg:hidden overflow-hidden transition-all duration-300 ease-in-out bg-white border-t border-gray-50 ${
          isMenuOpen ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'
        }`}
      >
        <div className="px-4 py-6 space-y-4">
          {navLinks.map((link) => (
            <Link 
              key={link.path}
              to={link.path}
              onClick={() => setIsMenuOpen(false)}
              className={`flex items-center justify-between p-4 rounded-2xl font-bold transition-all ${
                isActive(link.path) 
                ? 'bg-orange-50 text-orange-600' 
                : 'text-navy hover:bg-gray-50'
              }`}
            >
              {link.name}
              <ChevronRight size={18} className={isActive(link.path) ? 'opacity-100' : 'opacity-0'} />
            </Link>
          ))}
          <div className="pt-4 border-t border-gray-50">
            {user ? (
               <button 
                onClick={handleLogout}
                className="w-full flex items-center justify-center gap-2 p-4 bg-red-50 text-red-500 rounded-2xl font-bold hover:bg-red-100 transition-all"
              >
                <LogOut size={18} /> Sign Out
              </button>
            ) : (
              <Link 
                to="/auth"
                onClick={() => setIsMenuOpen(false)}
                className="w-full flex items-center justify-center gap-2 p-4 bg-navy text-white rounded-2xl font-bold hover:bg-orange-primary transition-all shadow-xl"
              >
                <User size={18} />
                Sign In to Your Account
              </Link>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { Share2, Calendar, Building2, CheckCircle2, ExternalLink } from 'lucide-react';
import { MOCK_SCHEMES } from '../constants';

const SchemeDetails: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const scheme = MOCK_SCHEMES.find(s => s.id === id);

  if (!scheme) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f9fafb]">
        <div className="text-center">
          <h2 className="text-3xl font-bold text-navy mb-4">Scheme Not Found</h2>
          <button onClick={() => navigate('/find-schemes')} className="text-orange-600 font-bold hover:underline">Go back to schemes</button>
        </div>
      </div>
    );
  }

  const handleApply = () => {
    window.open('https://india.gov.in', '_blank');
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] pb-24">
      {/* Breadcrumbs & Actions */}
      <div className="bg-white border-b sticky top-20 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-2 text-sm text-gray-500">
              <Link to="/" className="hover:text-orange-primary font-medium">Home</Link>
              <span className="text-gray-300">/</span>
              <Link to="/find-schemes" className="hover:text-orange-primary font-medium">Schemes</Link>
              <span className="text-gray-300">/</span>
              <span className="text-navy font-bold line-clamp-1">{scheme.title}</span>
            </div>
            <div className="flex items-center gap-3">
              <button className="p-2.5 rounded-xl border border-gray-100 hover:bg-gray-50 text-gray-600 transition-all active:scale-95">
                <Share2 size={18} />
              </button>
              <button 
                onClick={handleApply}
                className="px-6 py-2.5 bg-orange-primary hover:bg-orange-600 text-white font-bold rounded-xl transition-all shadow-lg shadow-orange-500/20 flex items-center gap-2 active:scale-95"
              >
                Apply Now <ExternalLink size={18} />
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-12">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
          {/* Main Content */}
          <div className="lg:col-span-8 space-y-12">
            {/* Header Card */}
            <div className="bg-white rounded-3xl p-8 md:p-12 shadow-sm border border-gray-100">
              <div className="flex flex-wrap gap-2 mb-8">
                <span className="px-4 py-1.5 bg-green-100 text-green-700 text-xs font-bold rounded-full">{scheme.category}</span>
                <span className="px-4 py-1.5 bg-blue-100 text-blue-700 text-xs font-bold rounded-full">{scheme.level}</span>
              </div>
              <h1 className="text-4xl font-extrabold text-navy mb-8 leading-tight">{scheme.title}</h1>
              <p className="text-lg text-gray-600 leading-relaxed mb-10">{scheme.description}</p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 py-8 border-t border-gray-100">
                <div className="flex items-center gap-4">
                  <div className="p-3 rounded-2xl bg-gray-50 text-navy">
                    <Building2 size={24} />
                  </div>
                  <div>
                    <div className="text-xs text-gray-400 font-bold uppercase tracking-wider mb-1">Ministry</div>
                    <div className="text-navy font-bold">{scheme.ministry}</div>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <div className="p-3 rounded-2xl bg-gray-50 text-navy">
                    <Calendar size={24} />
                  </div>
                  <div>
                    <div className="text-xs text-gray-400 font-bold uppercase tracking-wider mb-1">Last Updated</div>
                    <div className="text-navy font-bold">{scheme.updatedAt}</div>
                  </div>
                </div>
              </div>
            </div>

            {/* Sections */}
            {[
              { id: 'objectives', title: 'Objectives', data: scheme.objectives },
              { id: 'benefits', title: 'Benefits', data: scheme.benefits, highlight: true },
              { id: 'eligibility', title: 'Eligibility Criteria', data: scheme.eligibility },
              { id: 'documents', title: 'Required Documents', data: scheme.documents, grid: true },
              { id: 'howToApply', title: 'How to Apply', data: scheme.howToApply, ordered: true }
            ].map((section) => (
              <div key={section.id} id={section.id} className="bg-white rounded-3xl p-8 md:p-12 shadow-sm border border-gray-100">
                <h2 className="text-2xl font-extrabold text-navy mb-8 pb-4 border-b border-gray-50">{section.title}</h2>
                {section.grid ? (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {section.data.map((item, idx) => (
                      <div key={idx} className="p-4 bg-gray-50 rounded-2xl border border-gray-100 flex items-center gap-3 hover:bg-gray-100/50 transition-all">
                        <CheckCircle2 size={18} className="text-navy" />
                        <span className="text-navy font-medium text-sm">{item}</span>
                      </div>
                    ))}
                  </div>
                ) : section.ordered ? (
                  <div className="space-y-6">
                    {section.data.map((item, idx) => (
                      <div key={idx} className="flex gap-6">
                        <div className="flex-shrink-0 w-10 h-10 bg-navy rounded-full flex items-center justify-center text-white font-bold text-sm shadow-lg">
                          {idx + 1}
                        </div>
                        <p className="text-gray-600 font-medium leading-relaxed pt-2">{item}</p>
                      </div>
                    ))}
                  </div>
                ) : (
                  <ul className="space-y-4">
                    {section.data.map((item, idx) => (
                      <li key={idx} className={`flex gap-4 p-4 rounded-2xl transition-all ${section.highlight ? 'bg-green-50/50 border border-green-100' : 'hover:bg-gray-50'}`}>
                        <div className={`mt-1 flex-shrink-0 ${section.highlight ? 'text-green-600' : 'text-green-500'}`}>
                          <CheckCircle2 size={20} />
                        </div>
                        <span className="text-navy font-medium leading-relaxed">{item}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            ))}
          </div>

          {/* Sticky Sidebar */}
          <div className="lg:col-span-4 space-y-8">
            <div className="bg-navy rounded-3xl p-8 shadow-2xl sticky top-40">
                <h3 className="text-2xl font-bold text-white mb-6">Ready to Apply?</h3>
                <p className="text-gray-400 text-sm mb-8 leading-relaxed">Apply for this scheme directly on the official government portal. We've simplified the details for you.</p>
                <div className="space-y-4 mb-8">
                    <button 
                      onClick={handleApply}
                      className="w-full py-5 bg-orange-primary hover:bg-orange-600 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 active:scale-95"
                    >
                        Apply Now <ExternalLink size={20} />
                    </button>
                    <button 
                      onClick={() => navigate('/faqs')}
                      className="w-full py-5 bg-white/10 hover:bg-orange-primary hover:text-white text-white font-bold rounded-2xl border border-white/20 transition-all flex items-center justify-center gap-2 active:scale-95"
                    >
                        Need Help? Contact Us
                    </button>
                </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SchemeDetails;

import React, { useState, useEffect } from 'react';
import { User, MapPin, Calendar, Tag, Save, ChevronLeft, Sparkles, Loader2 } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { INDIAN_STATES_UTS } from '../constants';

const Settings: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [user, setUser] = useState<any>(null);

  const [profile, setProfile] = useState({
    first_name: '',
    last_name: '',
    street_address: '',
    city: '',
    state: '',
    age: '',
    category: 'General'
  });

  useEffect(() => {
    const checkAuth = () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);

      const savedProfile = localStorage.getItem(`profile_${parsedUser.id}`);
      if (savedProfile) {
        setProfile(JSON.parse(savedProfile));
      } else {
        setProfile({
          first_name: parsedUser.username || '',
          last_name: '',
          street_address: '',
          city: '',
          state: '',
          age: '',
          category: 'General'
        });
      }
      setLoading(false);
    };

    checkAuth();
  }, [navigate]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setProfile({ ...profile, [e.target.name]: e.target.value });
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setMessage(null);

    try {
      // Mock save to localStorage
      await new Promise(resolve => setTimeout(resolve, 500));
      localStorage.setItem(`profile_${user.id}`, JSON.stringify(profile));
      setMessage({ type: 'success', text: 'Profile updated successfully!' });
    } catch (err: any) {
      setMessage({ type: 'error', text: 'Failed to update profile' });
    } finally {
      setSaving(false);
    }
  };

  const labelClass = "text-[14px] font-bold text-[#1e293b]";
  const commonInputClass = "w-full pl-11 pr-4 py-3 rounded-xl border border-gray-200 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/5 focus:outline-none bg-white text-[15px] text-[#1e293b] font-medium placeholder:text-gray-400 transition-all";

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-orange-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fafb] pb-24 px-4">
      <div className="max-w-4xl mx-auto pt-12">
        <div className="flex items-center justify-between mb-10">
          <Link to="/" className="inline-flex items-center gap-2 text-[15px] font-bold text-gray-400 hover:text-[#1e293b] transition-all">
            <ChevronLeft size={20} /> Back to Home
          </Link>
          <div className="flex items-center gap-2 text-orange-500 font-bold bg-orange-50 px-4 py-2 rounded-full border border-orange-100">
            <Sparkles size={18} /> Profile Settings
          </div>
        </div>

        <div className="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
          <div className="px-8 py-10 bg-[#1e293b] text-white">
            <h1 className="text-3xl font-extrabold mb-2">My Profile Details</h1>
            <p className="text-gray-400">Manage your information to get better scheme recommendations.</p>
          </div>

          <form onSubmit={handleSave} className="p-8 md:p-12">
            {message && (
              <div className={`mb-8 p-4 rounded-2xl font-medium text-sm animate-in fade-in slide-in-from-top-2 ${
                message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'
              }`}>
                {message.text}
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest pb-2 border-b">Personal Information</h2>

                <div className="space-y-2">
                  <label className={labelClass}>First Name</label>
                  <div className="relative">
                    <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="first_name" placeholder="John"
                      value={profile.first_name} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Last Name</label>
                  <div className="relative">
                    <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="last_name" placeholder="Doe"
                      value={profile.last_name} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Age</label>
                  <div className="relative">
                    <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="number" name="age" placeholder="25"
                      value={profile.age} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Social Category</label>
                  <div className="relative">
                    <Tag className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <select 
                      name="category" value={profile.category} onChange={handleChange}
                      className={`${commonInputClass} appearance-none cursor-pointer`}
                    >
                      <option value="General">General</option>
                      <option value="OBC">OBC</option>
                      <option value="SC">SC</option>
                      <option value="ST">ST</option>
                      <option value="Minority">Minority</option>
                      <option value="EWS">EWS</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest pb-2 border-b">Address Details</h2>

                <div className="space-y-2">
                  <label className={labelClass}>Street Address</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="street_address" placeholder="123 Main St, Apartment 4B"
                      value={profile.street_address} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>City</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="city" placeholder="Mumbai"
                      value={profile.city} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>State / UT</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <select 
                      name="state" value={profile.state} onChange={handleChange}
                      className={`${commonInputClass} appearance-none cursor-pointer`}
                    >
                      <option value="">Select State</option>
                      {INDIAN_STATES_UTS.map(state => (
                        <option key={state} value={state}>{state}</option>
                      ))}
