import React, { useState } from 'react';
import { Mail, Lock, Sparkles, ChevronLeft, Eye, EyeOff, UserCircle, CheckCircle2, Send, KeyRound } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  updateProfile,
  sendEmailVerification,
  sendPasswordResetEmail,
  signOut,
  AuthError
} from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from '../lib/firebase';

const Auth: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [isForgotPassword, setIsForgotPassword] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [verificationEmail, setVerificationEmail] = useState<string | null>(null);
  const [resetEmailSent, setResetEmailSent] = useState<string | null>(null);
  const navigate = useNavigate();

  // Form states
  const [formData, setFormData] = useState({
    email: '',
    username: '',
    password: '',
    confirmPassword: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleAuthAction = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(null);

    if (isForgotPassword) {
      handleForgotPassword();
      return;
    }

    if (!isLogin && formData.password !== formData.confirmPassword) {
      setError("Passwords do not match");
      setLoading(false);
      return;
    }

    try {
      if (isLogin) {
        // Firebase Login
        try {
          const userCredential = await signInWithEmailAndPassword(auth, formData.email, formData.password);
          const user = userCredential.user;

          if (!user.emailVerified) {
            // User exists but email not verified
            await sendEmailVerification(user);
            setVerificationEmail(user.email);
            await signOut(auth);
            setLoading(false);
            return;
          }

          const userData = {
            email: user.email,
            username: user.displayName || user.email?.split('@')[0],
            id: user.uid
          };

          localStorage.setItem('gov_smart_user', JSON.stringify(userData));
          window.dispatchEvent(new Event('storage'));
          navigate('/');
        } catch (err: any) {
          const authError = err as AuthError;
          if (authError.code === 'auth/invalid-credential' || authError.code === 'auth/user-not-found' || authError.code === 'auth/wrong-password') {
            setError("Password or Email Incorrect");
          } else {
            setError("An error occurred during sign in. Please try again.");
          }
          setLoading(false);
        }
      } else {
        // Firebase Register
        try {
          const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
          const user = userCredential.user;

          // Update profile with name if provided
          if (formData.username) {
            await updateProfile(user, {
              displayName: formData.username
            });
          }

          // Create initial profile document in Firestore
          await setDoc(doc(db, "profiles", user.uid), {
            first_name: formData.username || user.email?.split('@')[0],
            last_name: '',
            email: user.email,
            age: '',
            state: '',
            occupation: '',
            income: '',
            category: 'General',
            created_at: new Date().toISOString()
          });

          // Send verification email
          await sendEmailVerification(user);

          // Show verification screen
          setVerificationEmail(user.email);

          // Sign out so they can't access app until they verify and log back in
          await signOut(auth);
          setLoading(false);
        } catch (err: any) {
          const authError = err as AuthError;
          if (authError.code === 'auth/email-already-in-use') {
            setError('User already exists. Sign in?');
          } else {
            setError(authError.message || 'An error occurred during registration.');
          }
          setLoading(false);
        }
      }
    } catch (err: any) {
      setError('An unexpected error occurred. Please try again.');
      setLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!formData.email) {
      setError("Please enter your email address first.");
      setLoading(false);
      return;
    }

    try {
      await sendPasswordResetEmail(auth, formData.email);
      setResetEmailSent(formData.email);
      setLoading(false);
    } catch (err: any) {
      const authError = err as AuthError;
      if (authError.code === 'auth/user-not-found') {
        setError("No user found with this email address.");
      } else {
        setError("Failed to send reset link. Please try again later.");
      }
      setLoading(false);
    }
  };

  const labelClass = "text-[14px] font-bold text-[#1e293b]";
  const commonInputClass = "w-full pl-11 pr-4 py-3 rounded-xl border border-gray-200 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/5 focus:outline-none bg-white text-[15px] text-[#1e293b] font-medium placeholder:text-gray-400 transition-all";

  if (resetEmailSent) {
    return (
      <div className="min-h-screen bg-[#f9fafb] flex flex-col items-center pt-8 pb-24 px-4 font-sans">
        <div className="w-full max-w-[460px] bg-white rounded-3xl shadow-2xl shadow-navy/5 border border-gray-100 p-8 md:p-12 text-center animate-in fade-in slide-in-from-bottom-4 duration-500 mt-20">
          <div className="w-20 h-20 bg-orange-50 rounded-full flex items-center justify-center mx-auto mb-8 text-orange-500">
            <Mail size={40} />
          </div>
          <h1 className="text-2xl font-black text-[#1e293b] mb-4">Reset Link Sent</h1>
          <p className="text-gray-500 leading-relaxed mb-10">
            We sent you a password change link to <span className="text-navy font-bold">{resetEmailSent}</span>.
          </p>
          <button 
            onClick={() => {
              setResetEmailSent(null);
              setIsForgotPassword(false);
              setIsLogin(true);
            }}
            className="w-full py-4 bg-[#1e293b] hover:bg-orange-primary text-white font-bold rounded-2xl shadow-xl shadow-navy/10 transition-all flex items-center justify-center text-[16px]"
          >
            Sign In
          </button>
        </div>
      </div>
    );
  }

  if (verificationEmail) {
    return (
      <div className="min-h-screen bg-[#f9fafb] flex flex-col items-center pt-8 pb-24 px-4 font-sans">
        <div className="w-full max-w-[460px] mb-8">
          <button 
            onClick={() => setVerificationEmail(null)}
            className="inline-flex items-center gap-2 text-[15px] font-bold text-gray-400 hover:text-[#1e293b] transition-all group"
          >
            <div className="w-8 h-8 rounded-full bg-white border border-gray-100 flex items-center justify-center shadow-sm group-hover:shadow transition-all">
              <ChevronLeft size={18} />
            </div>
            <span>Back to Login</span>
          </button>
        </div>

        <div className="w-full max-w-[460px] bg-white rounded-3xl shadow-2xl shadow-navy/5 border border-gray-100 p-8 md:p-12 text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="w-20 h-20 bg-orange-50 rounded-full flex items-center justify-center mx-auto mb-8 text-orange-500">
            <Send size={40} className="ml-1" />
          </div>
          <h1 className="text-2xl font-black text-[#1e293b] mb-4">Verify Your Email</h1>
          <p className="text-gray-500 leading-relaxed mb-10">
            We have sent you a verification email to <span className="text-navy font-bold">{verificationEmail}</span>. Verify it and log in.
          </p>
          <button 
            onClick={() => {
              setVerificationEmail(null);
              setIsLogin(true);
            }}
            className="w-full py-4 bg-[#1e293b] hover:bg-orange-primary text-white font-bold rounded-2xl shadow-xl shadow-navy/10 transition-all flex items-center justify-center text-[16px]"
          >
            Go to Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fafb] flex flex-col items-center pt-8 pb-24 px-4 font-sans">
      <div className="w-full max-w-[460px] mb-8">
        <Link 
          to="/" 
          className="inline-flex items-center gap-2 text-[15px] font-bold text-gray-400 hover:text-[#1e293b] transition-all group"
        >
          <div className="w-8 h-8 rounded-full bg-white border border-gray-100 flex items-center justify-center shadow-sm group-hover:shadow transition-all">
            <ChevronLeft size={18} />
          </div>
          <span>Back to Home</span>
        </Link>
      </div>

      <div className="w-full max-w-[460px]">
        <div className="text-center mb-8 flex flex-col items-center">
            <div className="bg-[#1e293b] w-16 h-16 rounded-full flex items-center justify-center mb-5 shadow-sm">
                <Sparkles className="text-white" size={32} />
            </div>
            <h1 className="text-3xl font-bold text-[#1e293b] tracking-tight">Gov-Smart</h1>
            <p className="text-gray-500 text-[15px] mt-1">AI-Powered Schemes Portal</p>
        </div>

        <div className="bg-white rounded-3xl shadow-2xl shadow-navy/5 border border-gray-100 w-full overflow-hidden">
          {!isForgotPassword && (
            <div className="flex p-1.5 bg-gray-50/80 m-6 rounded-2xl border border-gray-100">
              <button 
                type="button"
                onClick={() => { setIsLogin(true); setError(null); setSuccess(null); }}
                className={`flex-1 py-3 text-[15px] font-bold transition-all rounded-xl ${
                  isLogin 
                  ? 'bg-white text-[#1e293b] shadow-sm ring-1 ring-black/5' 
                  : 'text-gray-400 hover:text-gray-700'
                }`}
              >
                Sign In
              </button>
              <button 
                type="button"
                onClick={() => { setIsLogin(false); setError(null); setSuccess(null); }}
                className={`flex-1 py-3 text-[15px] font-bold transition-all rounded-xl ${
                  !isLogin 
                  ? 'bg-white text-[#1e293b] shadow-sm ring-1 ring-black/5' 
                  : 'text-gray-400 hover:text-gray-700'
                }`}
              >
                Create Account
              </button>
            </div>
          )}

          <form onSubmit={handleAuthAction} className="px-8 md:px-12 pb-12 pt-4">
            {isForgotPassword && (
              <div className="mb-6 flex items-center gap-3 text-navy font-black text-xl border-b border-gray-50 pb-4">
                <KeyRound className="text-orange-500" size={24} />
                Forgot Password
              </div>
            )}

            {error && (
              <div className="mb-8 p-4 bg-red-50 border border-red-100 text-red-600 text-sm rounded-2xl font-bold animate-in fade-in slide-in-from-top-2 flex justify-between items-center">
                <span>{error}</span>
                {error === 'User already exists. Sign in?' && (
                  <button 
                    type="button" 
                    onClick={() => { setIsLogin(true); setError(null); }}
                    className="ml-2 underline text-red-800"
                  >
                    Sign In
                  </button>
                )}
              </div>
            )}

            {success && (
              <div className="mb-8 p-4 bg-green-50 border border-green-100 text-green-700 text-sm rounded-2xl font-bold flex items-center gap-2 animate-in fade-in slide-in-from-top-2">
                <CheckCircle2 size={18} />
                {success}
              </div>
            )}

            <div className="space-y-6">
              {!isLogin && !isForgotPassword && (
                <div className="space-y-2">
                  <label className={labelClass}>Username</label>
                  <div className="relative">
                    <UserCircle className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="username" required placeholder="yourname"
                      value={formData.username} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>
              )}

              <div className="space-y-2">
                <label className={labelClass}>Email Address</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                  <input 
                    type="email" name="email" required placeholder="name@example.com"
                    value={formData.email} onChange={handleChange} className={commonInputClass}
                  />
                </div>
              </div>

              {!isForgotPassword && (
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <label className={labelClass}>Password</label>
                    {isLogin && (
                      <button 
                        type="button"
                        onClick={() => {
                          setIsForgotPassword(true);
                          setError(null);
                        }}
                        className="text-xs font-bold text-orange-600 hover:text-orange-700 transition-colors"
                      >
                        Forgot password?
                      </button>
                    )}
                  </div>
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type={showPassword ? "text" : "password"} name="password" required placeholder="••••••••"
                      value={formData.password} onChange={handleChange} className={commonInputClass}
                    />
                    <button 
                      type="button" onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-[#1e293b]"
                    >
                      {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>
                  </div>
                </div>
              )}

              {!isLogin && !isForgotPassword && (
                <div className="space-y-2">
                  <label className={labelClass}>Confirm Password</label>
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type={showPassword ? "text" : "password"} name="confirmPassword" required placeholder="••••••••"
                      value={formData.confirmPassword} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>
              )}
            </div>

            <button 
              type="submit"
              disabled={loading}
              className="w-full py-4 bg-[#1e293b] hover:bg-orange-primary text-white font-bold rounded-2xl shadow-xl shadow-navy/10 transition-all flex items-center justify-center mt-10 text-[16px] disabled:opacity-50"
            >
              {loading ? 'Processing...' : (isForgotPassword ? 'Get Reset Link' : (isLogin ? 'Sign In' : 'Create Account'))}
            </button>

            {isForgotPassword && (
              <button 
                type="button"
                onClick={() => {
                  setIsForgotPassword(false);
                  setError(null);
                }}
                className="w-full mt-4 py-2 text-sm font-bold text-gray-400 hover:text-navy transition-colors flex items-center justify-center gap-1"
              >
                <ChevronLeft size={14} /> Back to Sign In
              </button>
            )}
          </form>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import { User, MapPin, Calendar, Tag, Save, ChevronLeft, Sparkles, Loader2, Briefcase, Wallet } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { db } from '../lib/firebase';
import { INDIAN_STATES_UTS, OCCUPATIONS } from '../constants';

const Settings: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [user, setUser] = useState<any>(null);

  const [profile, setProfile] = useState({
    first_name: '',
    last_name: '',
    street_address: '',
    city: '',
    state: '',
    age: '',
    occupation: '',
    income: '',
    category: 'General'
  });

  useEffect(() => {
    const checkAuth = async () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);

      try {
        const docRef = doc(db, "profiles", parsedUser.id);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          setProfile({ ...profile, ...docSnap.data() });
        } else {
          // Initialize default if doesn't exist
          setProfile(prev => ({
            ...prev,
            first_name: parsedUser.username || '',
          }));
        }
      } catch (err) {
        console.error("Error fetching profile from Firestore:", err);
      } finally {
        setLoading(false);
      }
    };

    checkAuth();
  }, [navigate]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setProfile({ ...profile, [e.target.name]: e.target.value });
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setMessage(null);

    try {
      const docRef = doc(db, "profiles", user.id);
      await setDoc(docRef, profile, { merge: true });
      setMessage({ type: 'success', text: 'Profile updated in cloud successfully!' });
    } catch (err: any) {
      console.error("Save error:", err);
      setMessage({ type: 'error', text: 'Failed to update cloud profile' });
    } finally {
      setSaving(false);
    }
  };

  const labelClass = "text-[14px] font-bold text-[#1e293b]";
  const commonInputClass = "w-full pl-11 pr-4 py-3 rounded-xl border border-gray-200 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/5 focus:outline-none bg-white text-[15px] text-[#1e293b] font-medium placeholder:text-gray-400 transition-all";

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-orange-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fafb] pb-24 px-4">
      <div className="max-w-4xl mx-auto pt-12">
        <div className="flex items-center justify-between mb-10">
          <Link to="/" className="inline-flex items-center gap-2 text-[15px] font-bold text-gray-400 hover:text-[#1e293b] transition-all">
            <ChevronLeft size={20} /> Back to Home
          </Link>
          <div className="flex items-center gap-2 text-orange-500 font-bold bg-orange-50 px-4 py-2 rounded-full border border-orange-100">
            <Sparkles size={18} /> Cloud Profile Settings
          </div>
        </div>

        <div className="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
          <div className="px-8 py-10 bg-[#1e293b] text-white">
            <h1 className="text-3xl font-extrabold mb-2">My Information</h1>
            <p className="text-gray-400">Your details are stored securely in our cloud database for smart matching.</p>
          </div>

          <form onSubmit={handleSave} className="p-8 md:p-12">
            {message && (
              <div className={`mb-8 p-4 rounded-2xl font-medium text-sm animate-in fade-in slide-in-from-top-2 ${
                message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'
              }`}>
                {message.text}
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest pb-2 border-b">Personal Information</h2>

                <div className="space-y-2">
                  <label className={labelClass}>First Name</label>
                  <div className="relative">
                    <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="first_name" placeholder="John"
                      value={profile.first_name} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Last Name</label>
                  <div className="relative">
                    <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="last_name" placeholder="Doe"
                      value={profile.last_name} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className={labelClass}>Age</label>
                    <div className="relative">
                      <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                      <input 
                        type="number" name="age" placeholder="25"
                        value={profile.age} onChange={handleChange} className={commonInputClass}
                      />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className={labelClass}>Category</label>
                    <div className="relative">
                      <Tag className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                      <select 
                        name="category" value={profile.category} onChange={handleChange}
                        className={`${commonInputClass} appearance-none cursor-pointer`}
                      >
                        <option value="General">General</option>
                        <option value="OBC">OBC</option>
                        <option value="SC">SC</option>
                        <option value="ST">ST</option>
                      </select>
                    </div>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Occupation</label>
                  <div className="relative">
                    <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <select 
                      name="occupation" value={profile.occupation} onChange={handleChange}
                      className={`${commonInputClass} appearance-none cursor-pointer`}
                    >
                      <option value="">Select Occupation</option>
                      {OCCUPATIONS.map(occ => <option key={occ} value={occ}>{occ}</option>)}
                    </select>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Annual Family Income</label>
                  <div className="relative">
                    <Wallet className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <select 
                      name="income" value={profile.income} onChange={handleChange}
                      className={`${commonInputClass} appearance-none cursor-pointer`}
                    >
                      <option value="">Select Income Range</option>
                      <option value="Below 1 Lakh">Below 1 Lakh</option>
                      <option value="1 Lakh - 2.5 Lakh">1 Lakh - 2.5 Lakh</option>
                      <option value="2.5 Lakh - 5 Lakh">2.5 Lakh - 5 Lakh</option>
                      <option value="Above 5 Lakh">Above 5 Lakh</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest pb-2 border-b">Address Details</h2>

                <div className="space-y-2">
                  <label className={labelClass}>Street Address</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="street_address" placeholder="123 Main St"
                      value={profile.street_address} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>City</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="city" placeholder="Mumbai"
                      value={profile.city} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>State / UT</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <select 
                      name="state" value={profile.state} onChange={handleChange}
                      className={`${commonInputClass} appearance-none cursor-pointer`}
                    >
                      <option value="">Select State</option>
                      {INDIAN_STATES_UTS.map(state => (
                        <option key={state} value={state}>{state}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>
            </div>

            <div className="mt-12 flex justify-end">
              <button 
                type="submit"
                disabled={saving}
                className="px-10 py-4 bg-orange-primary hover:bg-orange-600 text-white font-bold rounded-2xl shadow-xl shadow-orange-500/20 transition-all flex items-center gap-2 disabled:opacity-50"
              >
                {saving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                {saving ? 'Saving to Cloud...' : 'Update Cloud Profile'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  Bookmark, 
  ArrowRight, 
  Zap, 
  CheckCircle2, 
  ChevronRight,
  UserCircle,
  TrendingUp,
  FileText,
  ShieldCheck,
  Bell
} from 'lucide-react';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../lib/firebase';
import { MOCK_SCHEMES } from '../constants';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<any>(null);
  const [savedCount, setSavedCount] = useState(0);

  useEffect(() => {
    const checkAuth = async () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }

      const user = JSON.parse(savedUser);

      try {
        const docRef = doc(db, "profiles", user.id);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          setProfile(docSnap.data());
        } else {
          setProfile({ first_name: user.username || 'User' });
        }
      } catch (err) {
        console.error("Dashboard profile fetch error:", err);
        setProfile({ first_name: user.username || 'User' });
      }

      const saved = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
      setSavedCount(saved.length);

      setLoading(false);
    };

    checkAuth();
  }, [navigate]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f9fafb]">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-navy border-t-orange-primary rounded-full animate-spin"></div>
          <p className="text-navy font-bold text-sm">Synchronizing your dashboard...</p>
        </div>
      </div>
    );
  }

  const stats = [
    { label: 'Smart Matches', value: '42', icon: <Zap size={24} />, color: 'bg-orange-50 text-orange-600', trend: '+12% this month' },
    { label: 'Saved Programs', value: savedCount, icon: <Bookmark size={24} />, color: 'bg-blue-50 text-blue-600', trend: 'Always accessible' },
    { label: 'Active Apps', value: '0', icon: <FileText size={24} />, color: 'bg-green-50 text-green-600', trend: 'Ready to start' },
  ];

  // Simple completion calculation
  const getCompletion = () => {
    if (!profile) return 0;
    const fields = ['first_name', 'last_name', 'age', 'state', 'occupation', 'income', 'category'];
    const filled = fields.filter(f => profile[f] && profile[f] !== '').length;
    return Math.round((filled / fields.length) * 100);
  };

  const completion = getCompletion();

  return (
    <div className="min-h-screen bg-[#f8fafc] pb-24 font-sans">
      <div className="bg-[#1e293b] pt-24 pb-40 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-orange-500/10 rounded-full blur-[120px] -translate-y-1/2 translate-x-1/2"></div>
        <div className="absolute bottom-0 left-0 w-[400px] h-[400px] bg-blue-500/5 rounded-full blur-[100px] translate-y-1/2 -translate-x-1/2"></div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div className="flex items-center gap-6">
              <div className="relative group">
                <div className="w-24 h-24 bg-gradient-to-br from-orange-400 to-orange-600 rounded-[2rem] flex items-center justify-center text-white text-4xl font-black shadow-2xl shadow-orange-500/40 transform group-hover:rotate-6 transition-all cursor-default">
                  {profile?.first_name?.[0] || 'U'}
                </div>
                <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-green-500 rounded-full border-4 border-[#1e293b] flex items-center justify-center">
                  <ShieldCheck size={14} className="text-white" />
                </div>
              </div>
              <div className="space-y-1">
                <h1 className="text-4xl font-extrabold text-white tracking-tight">
                  Hi, {profile?.first_name || 'User'}!
                </h1>
                <p className="text-gray-400 font-medium flex items-center gap-2">
                  <TrendingUp size={16} className="text-green-500" />
                  Your cloud profile is <span className="text-white">{completion}% complete</span>
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <Link 
                to="/find-schemes" 
                className="bg-white text-[#1e293b] hover:bg-orange-primary hover:text-white font-black py-4 px-10 rounded-2xl shadow-xl transition-all flex items-center gap-2 active:scale-95"
              >
                Scan for Schemes <ArrowRight size={20} />
              </Link>
              <button className="p-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl border border-white/10 transition-all">
                <Bell size={20} />
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-24 relative z-20">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {stats.map((stat, idx) => (
                <div key={idx} className="bg-white rounded-[2rem] p-8 border border-gray-100 shadow-sm hover:shadow-2xl transition-all group hover:-translate-y-1">
                  <div className={`w-14 h-14 ${stat.color} rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform`}>
                    {stat.icon}
