          ]
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9"
          }
        }
      });

      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          const base64Data = part.inlineData.data;
          setGeneratedImageUrl(`data:image/png;base64,${base64Data}`);
          break;
        }
      }
    } catch (error) {
      console.error("Visual Generation Error:", error);
    } finally {
      setIsGenerating(false);
    }
  };

  const featurePoints = [
    { title: "AI-Driven Discovery", desc: "Uses Gemini 3 Flash for semantic search and personalized eligibility matching.", icon: <Cpu size={20} /> },
    { title: "Multilingual Voice AI", desc: "STT/TTS support in 6 Indian languages for digital inclusivity.", icon: <Globe size={20} /> },
    { title: "Cloud Persistence", desc: "Real-time sync with Firebase Firestore for secure, cross-device profile management.", icon: <ShieldCheck size={20} /> },
    { title: "User-Centric Design", desc: "Premium Navy & Orange UI optimized for accessibility and low learning curve.", icon: <Layers size={20} /> }
  ];

  return (
    <div className="min-h-screen bg-[#0f172a] text-white pb-24">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-12">
        <div className="mb-12">
          <Link to="/" className="inline-flex items-center gap-2 text-gray-400 hover:text-orange-400 transition-all mb-8 font-bold">
            <ChevronLeft size={20} /> Back to App
          </Link>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
            <div>
              <h1 className="text-4xl font-black tracking-tight mb-2 flex items-center gap-3">
                <Presentation className="text-orange-500" size={36} />
                Presentation & Media Kit
              </h1>
              <p className="text-gray-400 font-medium">Tools and assets to help you explain the Gov-Smart ecosystem.</p>
            </div>
            <button 
              onClick={generatePresentationVisual}
              disabled={isGenerating}
              className="px-8 py-4 bg-orange-600 hover:bg-orange-500 rounded-2xl font-bold flex items-center gap-3 shadow-xl shadow-orange-900/20 transition-all disabled:opacity-50"
            >
              {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <Sparkles size={20} />}
              {generatedImageUrl ? 'Regenerate Slide Visual' : 'Generate PPT Visual'}
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
          {/* Main Content: Visual Area */}
          <div className="lg:col-span-8">
            <div className="aspect-video bg-[#1e293b] rounded-[2.5rem] border-2 border-dashed border-white/10 flex flex-col items-center justify-center overflow-hidden relative group">
              {generatedImageUrl ? (
                <>
                  <img src={generatedImageUrl} alt="Generated Presentation Visual" className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <a 
                      href={generatedImageUrl} 
                      download="gov-smart-presentation.png"
                      className="px-6 py-3 bg-white text-navy font-bold rounded-xl flex items-center gap-2 transform translate-y-4 group-hover:translate-y-0 transition-all"
                    >
                      <Download size={18} /> Download for PPT
                    </a>
                  </div>
                </>
              ) : (
                <div className="text-center p-12">
                  <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6 text-gray-500">
                    <ImageIcon size={40} />
                  </div>
                  <h3 className="text-xl font-bold mb-2">No Visual Generated</h3>
                  <p className="text-gray-500 max-w-sm mx-auto">Click the button above to generate a professional AI-powered isometric infographic for your presentation.</p>
                </div>
              )}
            </div>

            <div className="mt-8 p-8 bg-white/5 rounded-3xl border border-white/10">
              <h3 className="text-xl font-bold mb-6 flex items-center gap-2">
                <Layers className="text-orange-500" size={20} /> Solution Architecture
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="p-5 bg-navy/50 rounded-2xl border border-white/5">
                  <div className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-2">Frontend Stack</div>
                  <div className="font-bold">React 19 + Tailwind CSS</div>
                  <p className="text-xs text-gray-500 mt-1">Responsive, high-performance UI components with Lucide iconography.</p>
                </div>
                <div className="p-5 bg-navy/50 rounded-2xl border border-white/5">
                  <div className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-2">Intelligence Engine</div>
                  <div className="font-bold">Google Gemini 3 & 2.5</div>
                  <p className="text-xs text-gray-500 mt-1">Multi-modal AI for semantic search, matching, and multi-lingual voice.</p>
                </div>
                <div className="p-5 bg-navy/50 rounded-2xl border border-white/5">
                  <div className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-2">Backend & Security</div>
                  <div className="font-bold">Firebase Suite</div>
                  <p className="text-xs text-gray-500 mt-1">Firestore for cloud sync and Firebase Auth for secure citizen access.</p>
                </div>
                <div className="p-5 bg-navy/50 rounded-2xl border border-white/5">
                  <div className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-2">Scalability</div>
                  <div className="font-bold">Edge-Ready Deployment</div>
                  <p className="text-xs text-gray-500 mt-1">Cloud-native architecture designed to handle millions of scheme queries.</p>
                </div>
              </div>
            </div>
          </div>

          {/* Sidebar: Slide Content */}
          <div className="lg:col-span-4 space-y-8">
            <div className="bg-white/5 p-8 rounded-[2.5rem] border border-white/10">
              <h3 className="text-xl font-black mb-8 text-orange-500">Key Slide Points</h3>
              <div className="space-y-8">
                {featurePoints.map((point, i) => (
                  <div key={i} className="flex gap-4">
                    <div className="w-10 h-10 bg-orange-500/10 rounded-xl flex items-center justify-center text-orange-500 flex-shrink-0">
                      {point.icon}
                    </div>
                    <div>
                      <h4 className="font-bold text-sm mb-1">{point.title}</h4>
                      <p className="text-xs text-gray-400 leading-relaxed">{point.desc}</p>
                    </div>
                  </div>
                ))}
              </div>
              <button 
                onClick={() => {
                  const text = featurePoints.map(p => `${p.title}: ${p.desc}`).join('\n');
                  navigator.clipboard.writeText(text);
                  alert('Content copied for your PPT!');
                }}
                className="w-full mt-10 py-4 bg-white/10 hover:bg-white/20 rounded-2xl font-bold text-sm transition-all"
              >
                Copy Text for Slides
              </button>
            </div>

            <div className="bg-gradient-to-br from-orange-600 to-orange-800 p-8 rounded-[2.5rem] shadow-2xl">
              <h3 className="text-xl font-black mb-4">Pro Tip for PPT</h3>
              <p className="text-sm text-orange-100/80 leading-relaxed mb-6">
                When presenting the AI feature, emphasize that the portal uses **Semantic Search**. This means it understands "help for my farm" rather than just looking for exact keywords.
              </p>
              <div className="flex items-center gap-2 text-xs font-bold bg-white/10 p-3 rounded-xl border border-white/10">
                <Sparkles size={14} /> Driven by Google Gemini
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MediaKit;

